import{_ as a,o as i,c as e,ag as l}from"./chunks/framework.IxO3mcwW.js";const r="/getbiji-docs/images/getseed-quick-01.png",o="/getbiji-docs/images/getseed-quick-02.png",s="/getbiji-docs/images/getseed-quick-03.png",d="/getbiji-docs/images/getseed-quick-04.png",_=JSON.parse('{"title":"快速使用","description":"","frontmatter":{},"headers":[],"relativePath":"getseed/quickstart.md","filePath":"getseed/quickstart.md","lastUpdated":1773215704000}'),n={name:"getseed/quickstart.md"};function c(h,t,p,g,u,b){return i(),e("div",null,[...t[0]||(t[0]=[l('<h1 id="快速使用" tabindex="-1">快速使用 <a class="header-anchor" href="#快速使用" aria-label="Permalink to &quot;快速使用&quot;">​</a></h1><h2 id="认识录音卡" tabindex="-1">认识录音卡 <a class="header-anchor" href="#认识录音卡" aria-label="Permalink to &quot;认识录音卡&quot;">​</a></h2><p>录音卡有以下几个关键部件：</p><ul><li><strong>录音开关</strong>：向上拨动开始录音，向下回拨结束录音</li><li><strong>MARK 键</strong>：短按标记重点，长按记录闪念</li><li><strong>指示灯</strong>：显示当前状态</li><li><strong>磁吸背面</strong>：可吸附在手机背面进行通话录音</li></ul><h2 id="添加并激活设备" tabindex="-1">添加并激活设备 <a class="header-anchor" href="#添加并激活设备" aria-label="Permalink to &quot;添加并激活设备&quot;">​</a></h2><ol><li><strong>下载 Get笔记 APP</strong>：应用商店搜索「Get笔记」，安装并登录</li><li><strong>开启设备</strong>：长按 MARK 键 1 秒，指示灯亮白灯闪烁</li><li><strong>连接激活</strong>：打开 Get笔记 APP → 首页左上角菜单 → 点击「录音卡」→ 按指引连接</li></ol><div class="tip custom-block"><p class="custom-block-title">首次连接权益</p><ul><li>999 元礼盒款：送 1 年 Get笔记 PRO 会员</li><li>699 元标准款：送 3 个月 Get笔记 PRO 会员</li></ul></div><h2 id="开始-结束录音" tabindex="-1">开始/结束录音 <a class="header-anchor" href="#开始-结束录音" aria-label="Permalink to &quot;开始/结束录音&quot;">​</a></h2><table tabindex="0"><thead><tr><th>操作</th><th>方法</th><th>反馈</th></tr></thead><tbody><tr><td>开始录音</td><td>向上拨动录音开关</td><td>红灯长亮，振动 1 次</td></tr><tr><td>结束录音</td><td>向下回拨录音开关</td><td>灯灭，振动 2 次</td></tr><tr><td>标记重点</td><td>短按 MARK 键</td><td>振动提示</td></tr></tbody></table><h2 id="长按记录闪念" tabindex="-1">长按记录闪念 <a class="header-anchor" href="#长按记录闪念" aria-label="Permalink to &quot;长按记录闪念&quot;">​</a></h2><p>在录音开关<strong>关闭</strong>状态下：</p><ol><li>按住 MARK 键不放，振动 1 次，开始录音</li><li>边按边说话</li><li>松开 MARK 键，振动 2 次，结束录音</li><li>同步到 APP 后自动润色、去除口水词</li></ol><h2 id="手机通话录音" tabindex="-1">手机通话录音 <a class="header-anchor" href="#手机通话录音" aria-label="Permalink to &quot;手机通话录音&quot;">​</a></h2><ol><li>手机通话中，将录音卡吸附在手机背面</li><li>向上拨动录音开关，开始录音</li><li>通话结束后，向下回拨，结束录音</li></ol><p>支持：普通电话、微信视频通话、腾讯/钉钉/飞书会议</p><div class="warning custom-block"><p class="custom-block-title">注意</p><p>带蓝牙耳机时无法正常录到耳机中的声音，需使用听筒或扬声器模式。</p></div><h2 id="录音同步上传" tabindex="-1">录音同步上传 <a class="header-anchor" href="#录音同步上传" aria-label="Permalink to &quot;录音同步上传&quot;">​</a></h2><ol><li>保持手机蓝牙开启</li><li>打开 Get笔记 APP，点击右上角设备图标连接</li><li>连接后自动上传录音文件</li><li>可点击「快传」使用 WiFi 加速传输</li></ol><h2 id="截图演示" tabindex="-1">截图演示 <a class="header-anchor" href="#截图演示" aria-label="Permalink to &quot;截图演示&quot;">​</a></h2><div style="display:flex;gap:10px;overflow-x:auto;"><img src="'+r+'" alt="开箱" style="width:180px;border-radius:8px;"><img src="'+o+'" alt="绑定设备" style="width:180px;border-radius:8px;"><img src="'+s+'" alt="开始录音" style="width:180px;border-radius:8px;"><img src="'+d+'" alt="同步笔记" style="width:180px;border-radius:8px;"></div>',20)])])}const q=a(n,[["render",c]]);export{_ as __pageData,q as default};
